/// <reference types="vitest/config" />
import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { readFileSync } from "node:fs";
import path from "node:path";
import { defineConfig } from "vite";
import { devHeaders, parseHeaders } from "./src/lib/csp.ts";

// public/_headers (generated by `pnpm headers`) is what Cloudflare serves in
// production. The dev and preview servers send the same headers, so the
// browser enforces the CSP in e2e too; dev relaxes it just enough for Vite's
// inline refresh preamble and HMR socket.
const headers = parseHeaders(
  readFileSync(path.resolve(import.meta.dirname, "public/_headers"), "utf8"),
);

export default defineConfig({
  plugins: [react(), tailwindcss()],
  resolve: {
    alias: {
      "@": path.resolve(import.meta.dirname, "src"),
    },
  },
  server: { headers: devHeaders(headers) },
  preview: { headers },
  test: {
    environment: "jsdom",
    include: ["src/**/*.{test,spec}.{ts,tsx}"],
    setupFiles: ["./vitest.setup.ts"],
  },
});
